export const getTheoryByTopic = (topicId) => THEORY[topicId] || null;

export const getTheoryByCategory = (categoryId) =>
  Object.entries(THEORY)
    .filter(([, v]) => v.category === categoryId)
    .map(([k, v]) => ({ id: k, ...v }));
